mapper.select:
SELECT a.id AS "id", a.name AS "name", -- 使用COALESCE函数，优先使用关联表数据，为空时使用swm_person表中保存的数据（需要翻译） COALESCE(o.office_name, backup_o.office_name) AS "organization", COALESCE(p.position_name, backup_p.position_name) AS "workshop", COALESCE(fpl.prod_line_name, backup_fpl.prod_line_name) AS "process", COALESCE(wg.work_group_name, backup_wg.work_group_name) AS "team", hd.device_id AS "deviceId", NULL AS "workStatus", NULL AS "helmetStatus", a.personnel_status AS "personnelStatus", COALESCE(da_stats.attendance_count, 0) AS "attendanceCount", COALESCE(da_stats.working_hours, 0) AS "workingHours", COALESCE(da_stats.idle_hours, 0) AS "idleHours", a.identity_card AS "idCard", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks", a.status AS "status" FROM swm_person a -- 原有的关联查询（通过fms_worker关联） LEFT JOIN fms_worker f ON a.identity_card = f.identity_code COLLATE utf8mb4_general_ci LEFT JOIN js_sys_office o ON f.office_code = o.office_code AND o.zip_code IS NOT NULL LEFT JOIN fms_position_archive p ON f.work_shop_code = p.id AND p.type = 'CJ' LEFT JOIN fms_work_group wg ON f.work_group_id = wg.id LEFT JOIN fms_prod_line fpl ON fpl.id = wg.prod_line_id -- 备用关联查询（直接使用swm_person表中保存的ID进行翻译） LEFT JOIN js_sys_office backup_o ON a.company = backup_o.office_code COLLATE utf8mb4_general_ci AND backup_o.zip_code IS NOT NULL LEFT JOIN fms_position_archive backup_p ON a.department = backup_p.id COLLATE utf8mb4_general_ci AND backup_p.type = 'CJ' LEFT JOIN fms_work_group backup_wg ON a.team = backup_wg.id COLLATE utf8mb4_general_ci LEFT JOIN fms_prod_line backup_fpl ON a.prod_line = backup_fpl.id COLLATE utf8mb4_general_ci LEFT JOIN swm_helmet_device hd ON a.identity_card = hd.assigned_person LEFT JOIN ( SELECT da.employee_id, COUNT(CASE WHEN da.clock_in_time IS NOT NULL OR da.clock_out_time IS NOT NULL OR da.actual_hours > 0 OR da.effective_work_hours > 0 THEN 1 END) AS attendance_count, COALESCE(SUM(da.effective_work_hours), 0) AS working_hours, COALESCE(SUM(da.idle_hours), 0) AS idle_hours FROM swm_daily_attendance da WHERE da.status = '0'
AND DATE_FORMAT(da.attendance_date, '%Y-%m-%d') = #{timeValue}
AND DATE_FORMAT(da.attendance_date, '%Y-%u') = #{timeValue}
AND DATE_FORMAT(da.attendance_date, '%Y-%m') = #{timeValue}
AND DATE_FORMAT(da.attendance_date, '%Y-%m') = DATE_FORMAT(NOW(), '%Y-%m')
GROUP BY da.employee_id ) da_stats ON a.id = da_stats.employee_id
AND a.name LIKE CONCAT('%', #{name}, '%')
AND (o.office_name LIKE CONCAT('%', #{organization}, '%') OR backup_o.office_name LIKE CONCAT('%', #{organization}, '%'))
AND (p.position_name LIKE CONCAT('%', #{workshop}, '%') OR backup_p.position_name LIKE CONCAT('%', #{workshop}, '%'))
AND (fpl.prod_line_name LIKE CONCAT('%', #{process}, '%') OR backup_fpl.prod_line_name LIKE CONCAT('%', #{process}, '%'))
AND (wg.work_group_name LIKE CONCAT('%', #{team}, '%') OR backup_wg.work_group_name LIKE CONCAT('%', #{team}, '%'))
AND a.personnel_status = #{workStatus}
ORDER BY ${sqlMap.order.toSql()}
